        size = size.checked_add(1_u64.checked_add(4_u64.checked_add(u64::from(limits.me_model_shown_some))?)?)?.checked_add(4_u64.checked_add(u64::from(limits.me_model_accounts).checked_mul(4_u64)?)?)?;
